from pathlib import Path
r=Path(__file__).resolve().parents[3]
def mutate(file, pairs):
 p=r/file;s=p.read_text(encoding='utf-8')
 for old,new in pairs: s=s.replace(old,new)
 p.write_text(s,encoding='utf-8',newline='\n')
